window.docContents[119].resolve({"/Preface/#Hoare-Logic--Preface--Welcome":{"contents":"This is Hoare Logic, volume 2 of Software Foundations in\nLean.  It develops formal techniques for reasoning about what programs do.\nFor example, with techniques we present, one can prove that an algorithm\nsorts an array or that a compiler optimization does not incorrectly change\nthe behavior of the program it optimizes. This volume complements Type Systems,\nwhich develops techniques for establishing properties of all programs written\nin a given language; the two volumes can be read in either order, and both build\non the material in Logical Foundations.\n\n","context":"Hoare Logic\u0009Preface","header":"1.1. Welcome","id":"/Preface/#Hoare-Logic--Preface--Welcome"}});